def metrics(t):
 s=t['InstSection']['rows'];l=t['Loads']['rows'];n=t['Node']['rows'];nids={r['NodeId'] for r in n};sids={r['SectionId'] for r in s}
 adj=defaultdict(set);directed=defaultdict(set)
 for r in s:
  adj[r['FromNodeId']].add(r['ToNodeId']);adj[r['ToNodeId']].add(r['FromNodeId']);directed[r['FromNodeId']].add(r['ToNodeId'])
 def reach(graph):
  seen=set();todo=[t['InstFeeders']['rows'][0]['FeederId']]
  while todo:
   x=todo.pop()
   if x not in seen:seen.add(x);todo.extend(graph[x]-seen)
  return len(seen)
 return {'customers':sum(r.get(f'Phase{i}Customers') or 0 for r in l for i in [1,2,3]),'kva':sum(r.get(f'Phase{i}Kva') or 0 for r in l for i in [1,2,3]),'phase_customers':[sum(r.get(f'Phase{i}Customers') or 0 for r in l) for i in [1,2,3]],'phase_kva':[sum(r.get(f'Phase{i}Kva') or 0 for r in l) for i in [1,2,3]],'length_m':sum(r['SectionLength_MUL'] or 0 for r in s),'zero_sections':sum(r['SectionLength_MUL']==0 for r in s),'zero_loads':sum(all(not r.get(f'Phase{i}{q}') for i in [1,2,3] for q in ['Customers','Kva']) for r in l),'bad_endpoints':sum(r['FromNodeId'] not in nids or r['ToNodeId'] not in nids for r in s),'orphan_loads':sum(r['SectionId'] not in sids for r in l),'orphan_pv':sum(r['SectionId'] not in sids for r in t['InstDGens']['rows']),'reachable_undirected':reach(adj),'reachable_directed':reach(directed),'phase_patterns':dict(Counter(r['SectionPhases'] for r in s))}
